"""Core AFL-style greybox fuzzing simulation."""

from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Dict, Iterable, Iterator, List, Optional, Sequence, Set, Tuple

import numpy as np

from fuzzsim.bitmap import CoverageBitmap
from fuzzsim.mutation import bit_flip, byte_flip, delete_bytes, insert_bytes, random_byte
from fuzzsim.program_model import ExecutionTrace, SimulatedProgram
from fuzzsim.seed import TestCase


INTERESTING_8 = [-128, -1, 0, 1, 16, 32, 64, 100, 127]
INTERESTING_16 = [-32768, -129, 128, 255, 256, 512, 1000, 1024, 4096, 32767]
INTERESTING_32 = [-2147483648, -100663046, -32769, 32768, 65535, 65536, 100663045, 2147483647]


@dataclass(frozen=True)
class MutationCandidate:
    """A deterministic mutation emitted by a fuzzing stage."""

    data: bytes
    stage: str
    offset: int = 0
    width: int = 1


@dataclass(frozen=True)
class CalibrationResult:
    """Summary of AFL's seed calibration phase."""

    stable: bool
    stable_edges: Set[int]
    unstable_edges: Set[int]
    stability: float
    average_exec_time: float
    runs: int


@dataclass(frozen=True)
class AFLRunResult:
    """Final metrics for a fuzzing campaign."""

    paths_discovered: int
    unique_crashes: int
    corpus_size: int
    edge_coverage: float
    execs: int
    favored_seeds: int
    bitmap_coverage: int


class ForkServerSimulator:
    """Small model of AFL's fork server startup amortization."""

    def __init__(
        self,
        program: SimulatedProgram,
        startup_cost: float = 0.003,
        exec_overhead: float = 0.0002,
        use_forkserver: bool = True,
    ):
        self.program = program
        self.startup_cost = startup_cost
        self.exec_overhead = exec_overhead
        self.use_forkserver = use_forkserver
        self.started = False
        self.total_execs = 0

    def execute_once(self, data: bytes) -> ExecutionTrace:
        trace = self.program.trace(data)
        extra = self.exec_overhead
        if not self.use_forkserver or not self.started:
            extra += self.startup_cost
        self.started = True
        self.total_execs += 1
        return replace(trace, exec_time=trace.exec_time + extra)


class CrashDeduplicator:
    """Coverage-hash based crash deduplication."""

    def __init__(self):
        self.coverage_bitmap = CoverageBitmap()
        self.unique_crashes: Dict[str, TestCase] = {}

    def crash_hash(self, trace: ExecutionTrace) -> str:
        return self.coverage_bitmap.trace_hash(trace.bitmap_counts)

    def is_unique(self, trace: ExecutionTrace) -> bool:
        if not trace.is_crash:
            return False
        return self.crash_hash(trace) not in self.unique_crashes

    def record(self, testcase: TestCase):
        self.unique_crashes[testcase.metadata["crash_hash"]] = testcase


class AFLFuzzer:
    """A deterministic simulation of AFL's core fuzzing loop."""

    def __init__(
        self,
        program: SimulatedProgram,
        seed_inputs: Optional[Sequence[bytes]] = None,
        rng_seed: int = 42,
        user_dictionary: Optional[Iterable[bytes]] = None,
        calibration_runs: int = 3,
        max_input_size: int = 32,
    ):
        self.program = program
        self.bitmap = CoverageBitmap()
        self.edge_coverage: Set[int] = set()
        self.queue: List[TestCase] = []
        self.paths_seen: Set[Tuple[int, ...]] = set()
        self.path_frequencies: Dict[Tuple[int, ...], int] = {}
        self.crash_dedup = CrashDeduplicator()
        self.crashes: List[TestCase] = []
        self.rng = np.random.RandomState(rng_seed)
        self.forkserver = ForkServerSimulator(program)
        self.calibration_runs = calibration_runs
        self.iteration = 0
        self.max_input_size = max_input_size
        self.user_dictionary = sorted({bytes(token) for token in (user_dictionary or [])})
        self.auto_dictionary: Set[bytes] = set()

        for data in seed_inputs or []:
            self.add_to_queue(data=data, parent=None, source="seed", force=True)

    def _execute(self, data: bytes) -> ExecutionTrace:
        trace = self.forkserver.execute_once(data)
        self.paths_seen.add(trace.path_id)
        self.path_frequencies[trace.path_id] = self.path_frequencies.get(trace.path_id, 0) + 1
        return trace

    @staticmethod
    def _to_signed_bytes(value: int, width: int, endian: str) -> bytes:
        mask = (1 << (width * 8)) - 1
        return int(value & mask).to_bytes(width, endian, signed=False)

    @staticmethod
    def _overwrite_bytes(data: bytes, pos: int, token: bytes) -> bytes:
        buf = bytearray(data)
        if pos > len(buf):
            pos = len(buf)
        end = min(len(buf), pos + len(token))
        buf[pos:end] = token[:end - pos]
        if end - pos < len(token):
            buf.extend(token[end - pos:])
        return bytes(buf)

    def calibrate(self, data: bytes, runs: Optional[int] = None) -> CalibrationResult:
        """Run a testcase multiple times to estimate stability."""
        run_count = runs or self.calibration_runs
        traces = [self._execute(data) for _ in range(run_count)]
        coverage_sets = [set(trace.edge_ids) for trace in traces]
        stable_edges = set.intersection(*coverage_sets) if coverage_sets else set()
        union_edges = set.union(*coverage_sets) if coverage_sets else set()
        unstable_edges = union_edges - stable_edges
        stability = 1.0 if not union_edges else len(stable_edges) / len(union_edges)
        avg_exec_time = float(sum(trace.exec_time for trace in traces) / max(1, len(traces)))
        return CalibrationResult(
            stable=(len(unstable_edges) == 0),
            stable_edges=stable_edges,
            unstable_edges=unstable_edges,
            stability=stability,
            average_exec_time=avg_exec_time,
            runs=run_count,
        )

    def trim(self, data: bytes, target_trace: Optional[ExecutionTrace] = None) -> bytes:
        """Trim an input by removing power-of-two chunks while preserving coverage."""
        if len(data) <= 1:
            return data

        current = data
        trace = target_trace or self._execute(current)
        target_coverage = set(trace.edge_ids)
        remove_size = 1
        while remove_size * 2 < len(current):
            remove_size *= 2

        while remove_size >= 1 and len(current) > 1:
            pos = 0
            while pos < len(current):
                candidate = delete_bytes(current, pos, remove_size)
                candidate_trace = self._execute(candidate)
                if set(candidate_trace.edge_ids) == target_coverage:
                    current = candidate
                    trace = candidate_trace
                    continue
                pos += remove_size
            remove_size //= 2
        return current

    def generate_bitflip_mutations(self, data: bytes) -> Iterator[MutationCandidate]:
        bit_count = len(data) * 8
        for width in (1, 2, 4):
            if bit_count < width:
                continue
            for pos in range(bit_count - width + 1):
                yield MutationCandidate(bit_flip(data, pos, width), f"bitflip_{width}", pos, width)

    def generate_byteflip_mutations(self, data: bytes) -> Iterator[MutationCandidate]:
        for width in (1, 2, 4):
            if len(data) < width:
                continue
            for pos in range(len(data) - width + 1):
                yield MutationCandidate(byte_flip(data, pos, width), f"byteflip_{width * 8}", pos, width)

    def generate_arithmetic_mutations(self, data: bytes) -> Iterator[MutationCandidate]:
        for width in (1, 2, 4):
            if len(data) < width:
                continue
            limit = 1 << (width * 8)
            for pos in range(len(data) - width + 1):
                chunk = data[pos:pos + width]
                for endian in ("little", "big"):
                    current = int.from_bytes(chunk, endian, signed=False)
                    for delta in range(1, 36):
                        for op_name, value in (
                            ("arith_add", (current + delta) % limit),
                            ("arith_sub", (current - delta) % limit),
                        ):
                            replacement = value.to_bytes(width, endian, signed=False)
                            mutated = bytearray(data)
                            mutated[pos:pos + width] = replacement
                            yield MutationCandidate(
                                bytes(mutated),
                                f"{op_name}_{width * 8}_{endian}",
                                pos,
                                width,
                            )

    def generate_interesting_mutations(self, data: bytes) -> Iterator[MutationCandidate]:
        tables = {
            1: INTERESTING_8,
            2: INTERESTING_16,
            4: INTERESTING_32,
        }
        for width, values in tables.items():
            if len(data) < width:
                continue
            for pos in range(len(data) - width + 1):
                for endian in ("little", "big"):
                    for value in values:
                        mutated = bytearray(data)
                        mutated[pos:pos + width] = self._to_signed_bytes(value, width, endian)
                        yield MutationCandidate(
                            bytes(mutated),
                            f"interest_{width * 8}_{endian}",
                            pos,
                            width,
                        )

    def _all_dictionary_tokens(self) -> List[bytes]:
        return sorted(set(self.user_dictionary) | set(self.auto_dictionary))

    def generate_dictionary_mutations(self, data: bytes) -> Iterator[MutationCandidate]:
        tokens = self._all_dictionary_tokens()
        if not tokens:
            return
        for token in tokens:
            for pos in range(len(data) + 1):
                yield MutationCandidate(
                    self._overwrite_bytes(data, pos, token),
                    f"dict_overwrite_{len(token)}",
                    pos,
                    len(token),
                )
                if len(data) + len(token) <= self.max_input_size:
                    yield MutationCandidate(
                        insert_bytes(data, pos, token),
                        f"dict_insert_{len(token)}",
                        pos,
                        len(token),
                    )

    def _select_mutation_pos(self, data: bytes, allowed_positions: Optional[Sequence[int]]) -> int:
        if allowed_positions:
            return int(allowed_positions[self.rng.randint(0, len(allowed_positions))])
        return int(self.rng.randint(0, max(1, len(data))))

    def _apply_havoc_stack(
        self,
        data: bytes,
        num_mutations: int,
        allowed_positions: Optional[Sequence[int]] = None,
    ) -> bytes:
        result = data
        safe_positions = list(allowed_positions) if allowed_positions is not None else None
        for _ in range(num_mutations):
            if len(result) == 0:
                result = b"\x00"
                safe_positions = [0]
            op = int(self.rng.randint(0, 9))
            pos = self._select_mutation_pos(result, safe_positions)
            if op == 0:
                bit_pos = pos * 8 + int(self.rng.randint(0, 8))
                result = bit_flip(result, bit_pos, 1)
            elif op == 1:
                result = byte_flip(result, pos, 1)
            elif op == 2:
                delta = int(self.rng.randint(1, 36))
                buf = bytearray(result)
                buf[pos] = (buf[pos] + delta) & 0xFF
                result = bytes(buf)
            elif op == 3:
                delta = int(self.rng.randint(1, 36))
                buf = bytearray(result)
                buf[pos] = (buf[pos] - delta) & 0xFF
                result = bytes(buf)
            elif op == 4:
                interesting = int(self.rng.choice(INTERESTING_8))
                buf = bytearray(result)
                buf[pos] = interesting & 0xFF
                result = bytes(buf)
            elif op == 5:
                result = random_byte(result, pos, self.rng)
            elif op == 6 and len(result) > 1:
                if safe_positions is not None and pos not in safe_positions:
                    length = 1
                    result = delete_bytes(result, pos, length)
                    safe_positions = [p if p < pos else p - length for p in safe_positions if p != pos]
                elif safe_positions is None:
                    result = delete_bytes(result, pos, 1)
            elif op == 7 and len(result) < self.max_input_size:
                byte_value = int(self.rng.randint(0, 256))
                result = insert_bytes(result, pos, bytes((byte_value,)))
                if safe_positions is not None:
                    safe_positions = [p if p < pos else p + 1 for p in safe_positions]
            elif op == 8:
                tokens = self._all_dictionary_tokens()
                if tokens:
                    token = tokens[int(self.rng.randint(0, len(tokens)))]
                    result = self._overwrite_bytes(result, pos, token)
        return result

    def generate_havoc_mutations(
        self,
        data: bytes,
        cycles: int,
        allowed_positions: Optional[Sequence[int]] = None,
    ) -> Iterator[MutationCandidate]:
        for cycle in range(cycles):
            stack = 1 << int(self.rng.randint(1, 8))
            yield MutationCandidate(
                self._apply_havoc_stack(data, stack, allowed_positions=allowed_positions),
                "havoc",
                cycle,
                stack,
            )

    def splice_inputs(self, first: bytes, second: bytes) -> bytes:
        if len(first) < 2 or len(second) < 2:
            return first
        split = min(len(first), len(second)) // 2
        return first[:split] + second[split:]

    def generate_splice_mutations(self, data: bytes, partner_data: bytes, cycles: int) -> Iterator[MutationCandidate]:
        for cycle in range(cycles):
            spliced = self.splice_inputs(data, partner_data)
            stack = 1 << int(self.rng.randint(1, 8))
            yield MutationCandidate(
                self._apply_havoc_stack(spliced, stack),
                "splice",
                cycle,
                stack,
            )

    def calculate_performance_score(self, testcase: TestCase) -> float:
        """Constant AFL-style performance score based on seed quality."""
        if not self.queue:
            return 100.0
        avg_exec = sum(tc.exec_time for tc in self.queue) / len(self.queue)
        avg_cov = sum(len(tc.coverage) for tc in self.queue) / len(self.queue)

        score = 100.0
        if testcase.exec_time > 0:
            score *= min(3.0, max(0.25, avg_exec / testcase.exec_time))
        if avg_cov > 0:
            score *= min(2.0, max(0.5, len(testcase.coverage) / avg_cov))
        score *= 1.0 + min(testcase.depth, 10) * 0.05
        score *= max(0.1, testcase.stability)
        return float(max(1.0, min(score, 500.0)))

    def compute_energy(self, testcase: TestCase) -> int:
        """AFL's constant schedule uses the performance score directly."""
        testcase.perf_score = self.calculate_performance_score(testcase)
        testcase.energy = max(1.0, round(testcase.perf_score / 100.0))
        return int(testcase.energy)

    def _build_testcase(
        self,
        data: bytes,
        trace: ExecutionTrace,
        calibration: CalibrationResult,
        parent: Optional[TestCase],
        source: str,
    ) -> TestCase:
        depth = 0 if parent is None else parent.depth + 1
        metadata = {
            "source": source,
            "crash_hash": self.crash_dedup.crash_hash(trace) if trace.is_crash else "",
            "comparisons": trace.comparisons,
        }
        return TestCase(
            data=data,
            coverage=set(trace.edge_ids),
            exec_time=calibration.average_exec_time,
            is_crash=trace.is_crash,
            depth=depth,
            creation_time=self.iteration,
            stability=calibration.stability,
            path_id=trace.path_id,
            bitmap_signature=trace.coverage_signature,
            metadata=metadata,
        )

    def add_to_queue(
        self,
        data: bytes,
        parent: Optional[TestCase],
        source: str,
        force: bool = False,
        trace: Optional[ExecutionTrace] = None,
    ) -> Optional[TestCase]:
        """Execute, calibrate, trim, and enqueue a testcase when warranted."""
        initial_trace = trace or self._execute(data)
        new_edges = set(initial_trace.edge_ids) - self.edge_coverage
        is_unique_crash = self.crash_dedup.is_unique(initial_trace)
        should_keep = force or bool(new_edges) or is_unique_crash
        if not should_keep:
            return None

        calibration = self.calibrate(data)
        trimmed = data if initial_trace.is_crash else self.trim(data, target_trace=initial_trace)
        final_trace = initial_trace if trimmed == data else self._execute(trimmed)
        testcase = self._build_testcase(trimmed, final_trace, calibration, parent, source)

        testcase.perf_score = self.calculate_performance_score(testcase)
        self.bitmap.update(final_trace.bitmap_counts)
        self.edge_coverage.update(final_trace.edge_ids)
        self.paths_seen.add(final_trace.path_id)

        if force or set(final_trace.edge_ids) not in (set(tc.coverage) for tc in self.queue):
            self.queue.append(testcase)

        if testcase.is_crash and testcase.metadata["crash_hash"] and testcase.metadata["crash_hash"] not in self.crash_dedup.unique_crashes:
            self.crash_dedup.record(testcase)
            self.crashes.append(testcase)

        return testcase

    def _extract_auto_token(self, original: bytes, candidate: MutationCandidate, trace: ExecutionTrace, baseline: TestCase):
        if trace.path_id == baseline.path_id:
            return
        if candidate.stage.startswith("byteflip"):
            start = candidate.offset
            end = min(len(original), start + max(2, candidate.width))
            token = original[start:end]
        elif candidate.stage.startswith("bitflip"):
            start = candidate.offset // 8
            end = min(len(original), start + 2)
            token = original[start:end]
        else:
            return
        if 1 < len(token) <= 8:
            self.auto_dictionary.add(bytes(token))

    def deterministic_stage(self, testcase: TestCase):
        baseline = testcase
        stages = (
            self.generate_bitflip_mutations,
            self.generate_byteflip_mutations,
            self.generate_arithmetic_mutations,
            self.generate_interesting_mutations,
            self.generate_dictionary_mutations,
        )
        for generator in stages:
            for candidate in generator(testcase.data):
                trace = self._execute(candidate.data)
                self._extract_auto_token(testcase.data, candidate, trace, baseline)
                self.add_to_queue(candidate.data, parent=testcase, source=candidate.stage, trace=trace)
        testcase.metadata["deterministic_done"] = True

    def havoc_stage(self, testcase: TestCase):
        cycles = max(2, self.compute_energy(testcase) * 2)
        for candidate in self.generate_havoc_mutations(testcase.data, cycles=cycles):
            trace = self._execute(candidate.data)
            self.add_to_queue(candidate.data, parent=testcase, source=candidate.stage, trace=trace)

    def splice_stage(self, testcase: TestCase):
        if len(self.queue) < 2:
            return
        partners = [tc for tc in self.queue if tc is not testcase]
        if not partners:
            return
        partner = sorted(partners, key=lambda tc: (tc.times_chosen, tc.size, tc.creation_time))[0]
        cycles = max(1, self.compute_energy(testcase))
        for candidate in self.generate_splice_mutations(testcase.data, partner.data, cycles=cycles):
            trace = self._execute(candidate.data)
            self.add_to_queue(candidate.data, parent=testcase, source=candidate.stage, trace=trace)

    def cull_corpus(self) -> List[TestCase]:
        """Greedy set-cover culling using smallest, then fastest, seeds per edge."""
        for testcase in self.queue:
            testcase.is_favored = False
            testcase.unique_edges.clear()

        top_rated: Dict[int, TestCase] = {}
        for testcase in self.queue:
            for edge in testcase.coverage:
                best = top_rated.get(edge)
                if best is None:
                    top_rated[edge] = testcase
                    continue
                challenger = (testcase.size, testcase.exec_time, -testcase.depth)
                incumbent = (best.size, best.exec_time, -best.depth)
                if challenger < incumbent:
                    top_rated[edge] = testcase

        uncovered = set(top_rated)
        favored: List[TestCase] = []
        while uncovered:
            candidates = {top_rated[edge] for edge in uncovered}
            best = max(
                candidates,
                key=lambda tc: (
                    len(tc.coverage & uncovered),
                    -tc.size,
                    -tc.exec_time,
                    tc.depth,
                ),
            )
            best.is_favored = True
            best.unique_edges = set(best.coverage & uncovered)
            uncovered -= best.unique_edges
            favored.append(best)
        return favored

    def select_seed(self) -> TestCase:
        favored = [tc for tc in self.queue if tc.is_favored]
        use_favored = bool(favored) and bool(self.rng.rand() < 0.75)
        pool = favored if use_favored else self.queue
        ordered = sorted(
            pool,
            key=lambda tc: (
                tc.was_fuzzed,
                tc.times_chosen,
                -tc.is_favored,
                -tc.perf_score,
                tc.creation_time,
                tc.size,
            ),
        )
        chosen = ordered[0]
        chosen.times_chosen += 1
        return chosen

    def fuzz_one(self, testcase: TestCase):
        if not testcase.metadata.get("deterministic_done", False):
            self.deterministic_stage(testcase)
        self.havoc_stage(testcase)
        self.splice_stage(testcase)
        testcase.was_fuzzed = True
        testcase.fuzz_count += 1

    def run(self, max_queue_cycles: int = 4, max_total_execs: int = 100000) -> AFLRunResult:
        if not self.queue:
            raise ValueError("AFLFuzzer requires at least one seed input")

        idle_cycles = 0
        previous_paths = len(self.paths_seen)
        while self.iteration < max_queue_cycles and self.forkserver.total_execs < max_total_execs:
            self.cull_corpus()
            testcase = self.select_seed()
            self.fuzz_one(testcase)
            self.iteration += 1

            current_paths = len(self.paths_seen)
            if current_paths == previous_paths:
                idle_cycles += 1
            else:
                idle_cycles = 0
            previous_paths = current_paths

            if idle_cycles >= 2:
                break

        self.cull_corpus()
        return AFLRunResult(
            paths_discovered=len(self.paths_seen),
            unique_crashes=len(self.crashes),
            corpus_size=len(self.queue),
            edge_coverage=round(len(self.edge_coverage) / len(self.program.get_all_edge_ids()) * 100.0, 1),
            execs=self.forkserver.total_execs,
            favored_seeds=len([tc for tc in self.queue if tc.is_favored]),
            bitmap_coverage=self.bitmap.get_coverage_count(),
        )
